discrete EnergyCollectionSystem
port:
    event input real DetectSufficientEnergy;
    event output real ProvideDCPower;
state:
    initial state StandbyState
        when entry() then
            statehold(0);
        end;
        when receive(DetectSufficientEnergy) then
            transition(RunState);
        end;
    end;

    state RunState
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(StandbyState);
        end;
    end;
end;
end;

discrete PowerConversionSystem
port:
    event input real ReceiveDCCurrent;
    event output real ProvideACPower;
    event output real VoltageAdjustmentNeeded;
state:
    initial state StopState
        when entry() then
            statehold(0);
        end;
        when receive(ReceiveDCCurrent) then
            transition(DCtoACState);
        end;
    end;

    state DCtoACState
        when entry() then
            statehold(0);
        end;
        when receive(ReceiveDCCurrent) then
            transition(VoltageAdjustmentState);
            out
                send(VoltageAdjustmentNeeded, 1);
        end;
    end;

    state VoltageAdjustmentState
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(StopState);
            out
                send(ProvideACPower, 1);
        end;
    end;
end;
end;

discrete GridConnectionSystem
port:
    event input real SafetyChecksPassed;
    event input real GridSyncAchieved;
    event output real GridConnected;
state:
    initial state DisconnectedState
        when entry() then
            statehold(0);
        end;
        when receive(SafetyChecksPassed) then
            transition(SyncPreparationState);
        end;
    end;

    state SyncPreparationState
        when entry() then
            statehold(0);
        end;
        when receive(GridSyncAchieved) then
            transition(ConnectedState);
            out
                send(GridConnected, 1);
        end;
    end;

    state ConnectedState
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(DisconnectedState);
        end;
    end;
end;
end;

discrete MonitoringManagementSystem
port:
    event input real CriticalMetricsExceeded;
    event input real ProblemResolved;
    event output real NormalMonitoring;
    event output real AlarmStatus;
    event output real EmergencyResponse;
state:
    initial state NormalMonitoringState
        when entry() then
            statehold(0);
        end;
        when receive(CriticalMetricsExceeded) then
            transition(AlarmState);
        end;
    end;

    state AlarmState
        when entry() then
            statehold(0);
        end;
        when receive(ProblemResolved) then
            transition(EmergencyResponseState);
        end;
    end;

    state EmergencyResponseState
        when entry() then
            statehold(0);
        end;
        when receive(ProblemResolved) then
            transition(NormalMonitoringState);
        end;
    end;
end;
end;

couple DistributedPowerGenerationSystem
import architectureModels.EnergyCollectionSystem as ECS;
import architectureModels.PowerConversionSystem as PCS;
import architectureModels.GridConnectionSystem as GCS;
import architectureModels.MonitoringManagementSystem as MMS;
part:
    ECS energyCollectionInstance;
    PCS powerConversionInstance;
    GCS gridConnectionInstance;
    MMS monitoringManagementInstance;
connection:
    connect(energyCollectionInstance.ProvideDCPower, powerConversionInstance.ReceiveDCCurrent);
    connect(powerConversionInstance.ProvideACPower, gridConnectionInstance.SafetyChecksPassed);
    connect(gridConnectionInstance.GridConnected, monitoringManagementInstance.CriticalMetricsExceeded);
    connect(monitoringManagementInstance.NormalMonitoring, energyCollectionInstance.DetectSufficientEnergy);
    connect(monitoringManagementInstance.AlarmStatus, powerConversionInstance.AdjustVoltageInput);
    connect(monitoringManagementInstance.EmergencyResponse, gridConnectionInstance.GridSyncAchieved);
end;
